# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, confidence confirmation, steering hysteresis, and
    bounded reacquisition state to approach a stable target conservatively.
    """
    m = dict(memory or {})
    state = m.get("state", "IDLE")
    scan = m.get("scan_direction", "SCAN_LEFT")
    scan_hold = int(m.get("scan_hold", 0))
    stable = int(m.get("stable", 0))
    last_action = m.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    closing = float(observation["closing_risk"])
    heading = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        m["state"] = next_state
        m["last_action"] = action
        return action, confidence, m

    if safety < 0.60 or closing >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60
    if not confirmed:
        stable = 0
        m["stable"] = 0
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost > 0:
            if lost <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            if scan_hold <= 0:
                scan = "SCAN_RIGHT" if scan == "SCAN_LEFT" else "SCAN_LEFT"
                scan_hold = 2
            m["scan_direction"] = scan
            m["scan_hold"] = scan_hold - 1
            return emit(scan, 0.74, "REACQUIRE")
        return emit(scan, 0.70, "SEARCH")

    stable += 1
    m["stable"] = min(stable, 3)
    m["scan_hold"] = 0

    if track_age < 2 or stable < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading <= 15.0 and identity_conf >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return emit(action, 0.87, "APPROACH")

    # Hysteresis prevents needless instruction flips near the centerline.
    if last_action == "VEER_LEFT" and bearing < 8.0:
        bearing = 0.0
    elif last_action == "VEER_RIGHT" and bearing > -8.0:
        bearing = 0.0

    if bearing <= -18.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.89, "APPROACH")
    if bearing >= 18.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.89, "APPROACH")
    if observation["corridor_center"]:
        return emit("FORWARD", 0.91, "APPROACH")
    if bearing < 0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if bearing > 0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.78, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.78, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
